// Packs the port's NRO into app/celosia-nx-nro.js (one <script>), so the page puts it in every ZIP while still
// working opened straight from disk.   node make-nro-bundle.js <celosia_nx.nro> <out.js> <version label>
'use strict';
const fs = require('fs'), crypto = require('crypto');
const [, , nro, out, label] = process.argv;
const data = fs.readFileSync(nro);
const sha = crypto.createHash('sha256').update(data).digest('hex');
fs.writeFileSync(out, '// generated by wasm-src/make-nro-bundle.js\nself.CELOSIA_NRO={version:' + JSON.stringify(label) +
  ',size:' + data.length + ',sha256:"' + sha + '",b64:"' + data.toString('base64') + '"};\n');
console.log('nro bundle', out, fs.statSync(out).size, 'bytes, nro', data.length, 'sha', sha.slice(0, 12));
